class Poller:
    def __init__(self, fetch, min_interval=5, max_interval=300):
        self.fetch = fetch
        self.min_interval = min_interval
        self.max_interval = max_interval
        self.since = None
        self.interval = min_interval
        self._seen_at_since = set()

    def poll(self):
        items = self.fetch(self.since)
        new = []
        for item in items:
            stamp = item["updated_at"]
            if self.since is not None:
                if stamp < self.since:
                    continue
                if stamp == self.since and item["id"] in self._seen_at_since:
                    continue
            new.append(item)
        if items:
            top = max(item["updated_at"] for item in items)
            if self.since is None or top > self.since:
                self.since = top
                self._seen_at_since = set()
            self._seen_at_since |= {item["id"] for item in items if item["updated_at"] == self.since}
        if new:
            self.interval = max(self.min_interval, self.interval / 2)
        else:
            self.interval = min(self.max_interval, self.interval * 2)
        return new
